import 'package:flutter/material.dart';
import 'package:go_router/go_router.dart';
import 'package:supabase_flutter/supabase_flutter.dart';

import '../../core/localization/app_strings.dart';
import '../../core/theme/app_colors.dart';

class ManualAddressScreen extends StatefulWidget {const ManualAddressScreen({super.key});@override State<ManualAddressScreen> createState()=>_ManualAddressScreenState();}
class _ManualAddressScreenState extends State<ManualAddressScreen>{final form=GlobalKey<FormState>();final street=TextEditingController(),number=TextEditingController(),city=TextEditingController(),postal=TextEditingController();bool loading=false;String? error;@override void dispose(){street.dispose();number.dispose();city.dispose();postal.dispose();super.dispose();}Future<void> save()async{if(!(form.currentState?.validate()??false))return;final uid=Supabase.instance.client.auth.currentUser?.id;if(uid==null){context.go('/login');return;}setState(()=>loading=true);try{await Supabase.instance.client.from('user_addresses').insert({'user_id':uid,'label':'Home','street':street.text.trim(),'street_number':number.text.trim().isEmpty?null:number.text.trim(),'city':city.text.trim(),'postal_code':postal.text.trim().isEmpty?null:postal.text.trim(),'is_primary':true});if(mounted)context.go('/permissions/notifications');}catch(_){if(mounted)setState(()=>error=AppStrings.of(context).t('errorGeneric'));}finally{if(mounted)setState(()=>loading=false);}}@override Widget build(BuildContext context){final s=AppStrings.of(context);return Scaffold(appBar:AppBar(title:Text(s.t('address'))),body:SafeArea(child:Form(key:form,child:ListView(padding:const EdgeInsets.all(24),children:[Text(s.t('primaryAddress'),style:Theme.of(context).textTheme.headlineMedium),const SizedBox(height:10),Text(s.t('addressBody'),style:Theme.of(context).textTheme.bodyLarge?.copyWith(color:AppColors.muted)),const SizedBox(height:26),TextFormField(controller:street,decoration:InputDecoration(labelText:s.t('street')),validator:(v)=>v==null||v.trim().isEmpty?'*':null),const SizedBox(height:12),TextFormField(controller:number,decoration:InputDecoration(labelText:s.t('streetNumber'))),const SizedBox(height:12),TextFormField(controller:city,decoration:InputDecoration(labelText:s.t('city')),validator:(v)=>v==null||v.trim().isEmpty?'*':null),const SizedBox(height:12),TextFormField(controller:postal,decoration:InputDecoration(labelText:s.t('postalCode'))),if(error!=null)...[const SizedBox(height:12),Text(error!,style:const TextStyle(color:AppColors.danger))],const SizedBox(height:22),SizedBox(height:56,child:FilledButton(onPressed:loading?null:save,child:loading?const CircularProgressIndicator(color:Colors.white):Text(s.t('saveAddress'))))]))));}}